const apiBaseUrl=(import.meta.env.VITE_API_BASE_URL??'').replace(/\/+$/,'');
function apiUrl(path:string):string{
  if(window.location.hostname.endsWith('.pages.dev')&&!apiBaseUrl)throw new Error('API is not configured. Set VITE_API_BASE_URL in the Cloudflare Pages build settings and redeploy.');
  if(window.location.protocol==='https:'&&apiBaseUrl.startsWith('http://'))throw new Error('The API URL must use HTTPS when the site is loaded over HTTPS.');
  return `${apiBaseUrl}/api/v1${path}`;
}
async function api<T>(path:string,token:string|null,init:RequestInit={}):Promise<T>{
  const response=await fetch(apiUrl(path),{...init,headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`}:{ }),...init.headers}});
  const data=await response.json().catch(()=>null) as {message?:string|string[]}|null;
  if(!response.ok){const message=Array.isArray(data?.message)?data.message.join(' '):data?.message;throw new Error(message||'Request failed. Please try again.');}
  if(data===null)throw new Error('The API returned an invalid response. Check that VITE_API_BASE_URL points to the backend API, not the frontend site.');
  return data as T;
}
async function uploadFile(path:string,token:string|null,file:File):Promise<{success:boolean}>{
  const form=new FormData();form.append('file',file);
  const response=await fetch(apiUrl(path),{method:'POST',headers:token?{Authorization:`Bearer ${token}`}:{},body:form});
  const data=await response.json().catch(()=>null) as {message?:string|string[]}|null;
  if(!response.ok){const message=Array.isArray(data?.message)?data.message.join(' '):data?.message;throw new Error(message||'Image upload failed. Please try again.');}
  return data as {success:boolean};
}
async function resizeImageTo150(file:File):Promise<File>{
  const imageUrl=URL.createObjectURL(file);
  try{
    const image=await new Promise<HTMLImageElement>((resolve,reject)=>{
      const element=new window.Image();
      element.onload=()=>resolve(element);
      element.onerror=()=>reject(new Error('The selected image could not be opened.'));
      element.src=imageUrl;
    });
    const canvas=document.createElement('canvas');
    canvas.width=150;
    canvas.height=150;
    const context=canvas.getContext('2d');
    if(!context)throw new Error('Image resizing is not supported by this browser.');
    const scale=Math.min(150/image.naturalWidth,150/image.naturalHeight);
    const width=image.naturalWidth*scale;
    const height=image.naturalHeight*scale;
    context.clearRect(0,0,150,150);
    context.drawImage(image,(150-width)/2,(150-height)/2,width,height);
    const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(result=>result?resolve(result):reject(new Error('The resized image could not be created.')),'image/png'));
    return new File([blob],`${file.name.replace(/\.[^.]+$/,'')||'image'}-150.png`,{type:'image/png'});
  }finally{
    URL.revokeObjectURL(imageUrl);
  }
}
function useServerPage<T>(token:string|null,path:string,filters:Record<string,string>={},reloadKey=0,initialPageSize=25){
  const [data,setData]=useState<ApiPage<T>>({items:[],total:0,page:1,pageSize:initialPageSize,totalPages:0});
  const [page,setPage]=useState(1);
  const [pageSize,setPageSizeValue]=useState(initialPageSize);
  const [search,setSearchValue]=useState('');
  const [loading,setLoading]=useState(true);
  const [error,setError]=useState('');
  const filterKey=JSON.stringify(filters);
  useEffect(()=>{setPage(1);},[filterKey]);
  useEffect(()=>{
    if(!token)return;
    let active=true;
    const timer=window.setTimeout(()=>{
      const query=new URLSearchParams({page:String(page),pageSize:String(pageSize),...filters});
      if(search.trim())query.set('search',search.trim());
      setLoading(true);
      api<ApiPage<T>>(`${path}?${query.toString()}`,token).then(result=>{if(active){setData(result);setError('');}}).catch(failure=>{if(active)setError((failure as Error).message);}).finally(()=>{if(active)setLoading(false);});
    },search?250:0);
    return()=>{active=false;window.clearTimeout(timer);};
  },[token,path,page,pageSize,search,filterKey,reloadKey]);
  function setSearch(value:string){setSearchValue(value);setPage(1);}
  function changePageSize(value:number){setPageSizeValue(value);setPage(1);}
  return {data,page,pageSize,loading,error,search,setSearch,setPage,setPageSize:changePageSize};
}
function dateLabel(date:string){const value=/^\d{4}-\d{2}-\d{2}$/.test(date)?new Date(`${date}T00:00:00`):new Date(date);return new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(value);}
function dateKey(date:Date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function dateKeyInTimeZone(date:Date,timeZone:string){const parts=new Intl.DateTimeFormat('en-CA',{timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const part=(type:string)=>parts.find(item=>item.type===type)?.value||'';return `${part('year')}-${part('month')}-${part('day')}`;}
function dateFromKey(key:string){const [year,month,day]=key.split('-').map(Number);return new Date(year,month-1,day);}
function addDays(date:Date,days:number){const next=new Date(date);next.setDate(next.getDate()+days);return next;}
function mondayOf(date:Date){const day=new Date(date.getFullYear(),date.getMonth(),date.getDate());day.setDate(day.getDate()-((day.getDay()+6)%7));return day;}
function statusClass(status:string){return `status status-${status}`;}
function jobAssignee(job:Job){return job.contractorName?`${job.contractorName} (contractor)`:job.assignedName||'Unassigned';}
function hasPermission(user:User|null,permission:string){return Boolean(user&&(user.systemRole==='admin'||hasPermissionFor(user.permissions,permission)));}
function hasPermissionFor(permissions:string[],permission:string){
  const implies:Record<string,string[]>={'customers.write':['customers.read'],'jobs.create':['jobs.read','customers.read'],'jobs.update':['jobs.read','team.read'],'schedule.read':['jobs.read'],'equipment.write':['equipment.read','customers.read'],'worklogs.write':['worklogs.read'],'attachments.write':['attachments.read'],'inventory.write':['inventory.read'],'maintenance.write':['maintenance.read'],'team.manage':['team.read'],'settings.manage':['settings.read']};
  return permissions.includes(permission)||permissions.some(granted=>implies[granted]?.includes(permission));
}

